267	static void watch_sys_gesture_event_cb(lv_event_t *e)
268	{
269	    lv_event_code_t code = lv_event_get_code(e);
270	    lv_indev_t *indev = lv_indev_active();
271	    if (!indev) return;
272	
273	    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
274	
275	    switch (code)
276	    {
277	    case LV_EVENT_GESTURE:
278	        if (dir == LV_DIR_LEFT)
279	        {
280	            if (!strcmp(mpd->current_page, HOME_PAGE))
281	            {
282	                LV_LOG_USER("LV_DIR_LEFT: switching to applist via tileview");
283	                // Use tileview for smooth sliding animation
284	                nav_to_applist_tile();
285	                g_current_page = PAGE_APPLIST;
286	            }
287	            else
288	            {
289	                bool is_home_page = !strcmp(mpd->current_page, HOME_PAGE);
290	                LV_LOG_USER("LV_DIR_LEFT + currentPage: %s, is_home_page %d \n", mpd->current_page, is_home_page);
291	            }
292	        }
293	        if (dir == LV_DIR_RIGHT)
294	        {
295	            LV_LOG_USER("LV_DIR_RIGHT  currentPage: %s \n", mpd->current_page);
296	            if (!strcmp(mpd->current_page, HOME_PAGE))
297	            {
298	                LV_LOG_USER("LV_DIR_RIGHT currentPage: %s  \n", mpd->current_page);
299	            }
300	            else
301	            {
302	                LV_LOG_USER("Before LV_DIR_RIGHT currentPage: %s %d \n", mpd->current_page, (mpd->appListCenter != NULL));
303	                // If on applist page, use tileview to navigate back to home
304	                if (!strcmp(mpd->current_page, APPS_PAGE))
305	                {
306	                    LV_LOG_USER("LV_DIR_RIGHT: switching to home via tileview");
307	                    nav_to_home_tile();
308	                    g_current_page = PAGE_HOME;
309	                }
310	                else
311	                {
312	                    // For other pages, use existing logic
313	                    if (mpd->appListCenter != NULL) {
314	                        lv_anim_delete(mpd->appListCenter, anim_translate_y_cb);
315	                        applist_hide_page();   /* 删列表 ui_bg 子树 + 清静态指针 */
316	                        lv_obj_delete(mpd->appListCenter);
317	                        mpd->appListCenter = NULL;
318	                    }
319	
320	                    /* 恢复表盘：取消 HIDDEN（timer 一直走，秒针已是当前角度，直接显示无跳动） */
321	                    watch_show();
322	                    watch_show();
323	                    g_current_page = PAGE_HOME;
324	
325	                    strcpy(mpd->current_page, HOME_PAGE);
326	                }
327	            }
328	        }
329	        break;
330	    default:
331	        break;
332	    }
