53	static void update_stopwatch_time(void)
54	{
55	    uint32_t current_time;
56	    uint32_t total_elapsed;
57	    char time_str[16];
58	    
59	    if (stopwatch_running) {
60	        current_time = lv_tick_get();
61	        total_elapsed = stopwatch_elapsed_time + (current_time - stopwatch_start_time);
62	    } else {
63	        total_elapsed = stopwatch_elapsed_time;
64	    }
65	
66	    uint32_t minutes = total_elapsed / 60000;
67	    uint32_t seconds = (total_elapsed % 60000) / 1000;
68	    uint32_t milliseconds = total_elapsed % 1000;
69	    
70	    snprintf(time_str, sizeof(time_str), "%02lu:%02lu.%03lu", minutes, seconds, milliseconds);
71	    lv_label_set_text(stopwatch_label, time_str);
72	}
