163	//手势事件处理函数
164	static void gesture_event_handler(lv_event_t *e)
165	{
166	    lv_event_code_t code = lv_event_get_code(e);
167	    if (code != LV_EVENT_PRESSED && code != LV_EVENT_RELEASED) return;
168	    lv_obj_t *obj = lv_event_get_target(e);
169	    lv_indev_t *indev = lv_event_get_indev(e);
170	    
171	    if (!indev) return;
172	    
173	    lv_point_t point;
174	    lv_indev_get_point(indev, &point);
175	    
176	    switch (code) {
177	        case LV_EVENT_PRESSED:
178	            gesture_start_x = point.x;
179	            gesture_start_y = point.y;
180	            gesture_in_progress = true;
181	            break;
182	        case LV_EVENT_RELEASED:
183	            if (gesture_in_progress) {
184	                int delta_x = point.x - gesture_start_x;
185	                int delta_y = point.y - gesture_start_y;
186	                
187	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
188	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
189	                    // 修改：右滑隐藏秒表界面
190	                    exit_stopwatch();
191	                }
192	                
193	                gesture_in_progress = false;
194	            }
195	            break;
196	        default:
197	            break;
198	    }
199	}
