97	void lv_tileview_set_tile_by_index(lv_obj_t * tv, uint32_t col_id, uint32_t row_id, lv_anim_enable_t anim_en)
98	{
99	    lv_obj_update_layout(tv);
100	
101	    int32_t w = lv_obj_get_content_width(tv);
102	    int32_t h = lv_obj_get_content_height(tv);
103	
104	    int32_t tx = col_id * w;
105	    int32_t ty = row_id * h;
106	
107	    uint32_t i;
108	    for(i = 0; i < lv_obj_get_child_count(tv); i++) {
109	        lv_obj_t * tile_obj = lv_obj_get_child(tv, i);
110	        int32_t x = lv_obj_get_x(tile_obj);
111	        int32_t y = lv_obj_get_y(tile_obj);
112	        if(x == tx && y == ty) {
113	            lv_tileview_set_tile(tv, tile_obj, anim_en);
114	            return;
