150	static void tileview_event_cb(lv_event_t * e)
151	{
152	    lv_event_code_t code = lv_event_get_code(e);
153	    lv_obj_t * obj = lv_event_get_current_target(e);
154	    lv_tileview_t * tv = (lv_tileview_t *) obj;
155	
156	    if(code == LV_EVENT_SCROLL_END) {
157	        lv_indev_t * indev = lv_indev_active();
158	        if(indev && indev->state == LV_INDEV_STATE_PRESSED) {
159	            return;
160	        }
161	
162	        int32_t w = lv_obj_get_content_width(obj);
163	        int32_t h = lv_obj_get_content_height(obj);
164	
165	        lv_point_t scroll_end;
166	        lv_obj_get_scroll_end(obj, &scroll_end);
167	        int32_t left = scroll_end.x;
168	        int32_t top = scroll_end.y;
169	
170	        int32_t tx = ((left + (w / 2)) / w) * w;
171	        int32_t ty = ((top + (h / 2)) / h) * h;
172	
173	        lv_dir_t dir = LV_DIR_ALL;
174	        uint32_t i;
175	        for(i = 0; i < lv_obj_get_child_count(obj); i++) {
176	            lv_obj_t * tile_obj = lv_obj_get_child(obj, i);
177	            int32_t x = lv_obj_get_x(tile_obj);
178	            int32_t y = lv_obj_get_y(tile_obj);
179	            if(x == tx && y == ty) {
180	                lv_tileview_tile_t * tile = (lv_tileview_tile_t *)tile_obj;
181	                tv->tile_act = (lv_obj_t *)tile;
182	                dir = tile->dir;
183	                lv_obj_send_event(obj, LV_EVENT_VALUE_CHANGED, NULL);
184	                break;
185	            }
186	        }
187	        lv_obj_set_scroll_dir(obj, dir);
188	    }
189	}
190	#endif /*LV_USE_TILEVIEW*/
