// Tileview event callback to handle tile changes
static void tileview_event_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *tv = lv_event_get_target(e);

    if (code == LV_EVENT_VALUE_CHANGED)
    {
        lv_obj_t *tile = lv_tileview_get_tile_active(tv);
        if (tile == mpd->tile_applist)
        {
            LV_LOG_USER("Tileview: switched to applist tile");
            strcpy(mpd->current_page, APPS_PAGE);
            // Start applist UI when entering applist tile
            applist_create_list(mpd->tile_applist);
        }
        else if (tile == mpd->tile_home)
        {
            LV_LOG_USER("Tileview: switched to home tile");
            strcpy(mpd->current_page, HOME_PAGE);
            // Clean up applist when returning to home tile
            // NOTE: appListCenter is always NULL in tileview path,
            // so we must call applist_hide_page() unconditionally
            // to clean up the UI objects created in the tile.
            applist_hide_page();
            mpd->appListCenter = NULL;
        }
    }
}

