// Deferred timer callback: create applist UI after scroll completes.
// Creating UI objects synchronously inside LV_EVENT_VALUE_CHANGED (which fires
// during LV_EVENT_SCROLL_END) can conflict with the tileview's scroll state.
static void applist_create_timer_cb(lv_timer_t *timer)
{
    lv_timer_delete(timer);  /* one-shot: delete self first */
    LV_LOG_USER("Deferred applist_create_list");
    applist_create_list(mpd->tile_applist);
}

// Deferred timer callback: clean up applist UI after scroll completes.
static void applist_cleanup_timer_cb(lv_timer_t *timer)
{
    lv_timer_delete(timer);  /* one-shot: delete self first */
    LV_LOG_USER("Deferred applist_hide_page");
    applist_hide_page();
    mpd->appListCenter = NULL;
}

// Tileview event callback to handle tile changes
static void tileview_event_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *tv = lv_event_get_target(e);

    if (code == LV_EVENT_VALUE_CHANGED)
    {
        lv_obj_t *tile = lv_tileview_get_tile_active(tv);
        if (tile == mpd->tile_applist)
        {
            LV_LOG_USER("Tileview: switched to applist tile");
            strcpy(mpd->current_page, APPS_PAGE);
            /* Defer UI creation to next tick: creating objects during
             * LV_EVENT_SCROLL_END can corrupt tileview scroll state. */
            lv_timer_create(applist_create_timer_cb, 1, NULL);
        }
        else if (tile == mpd->tile_home)
        {
            LV_LOG_USER("Tileview: switched to home tile");
            strcpy(mpd->current_page, HOME_PAGE);
            /* Defer cleanup to next tick for the same reason. */
            lv_timer_create(applist_cleanup_timer_cb, 1, NULL);
        }
    }
}

